// engine.ts — framework-agnostic renderer. Extracted from the source
// component's effect body: fresh canvas per instance, GL setup, live uniforms,
// the rAF loop, IntersectionObserver + visibilitychange + prefers-reduced-motion
// + ResizeObserver wiring, dt clamp, premultiplied blending, context-loss
// recovery, full cleanup.

import { parseColor } from "./color";
import { seedOffset } from "./seed";
import { buildProgram } from "./shader";

/** A per-60Hz-frame lerp amount, rescaled to the real frame delta.
 *
 *  `x += (target - x) * k` with a constant k is not a speed, it is a speed PER
 *  FRAME: the same 0.08 settles 2.4x faster on a 144Hz display than on a 60Hz
 *  one, and crawls through a slow frame. Every follow in here goes through this
 *  instead, so the motion is the same everywhere and a dropped frame is caught
 *  up rather than skipped. */
const fri = (k: number, dt: number): number => 1 - Math.pow(1 - k, dt * 60);

/** A stop in a scroll-driven colour journey. */
export interface ColorStop {
  /** Progress 0..1 at which this stop applies. */
  at: number;
  /** Line colour at this stop (any CSS color). */
  color: string;
  /** Line opacity at this stop. */
  opacity: number;
}

export interface TopolinesOptions {
  /** Any string. Same seed = same starting pattern. */
  seed?: string;
  /** Time multiplier. ~0.012 ≈ 10px/sec of contour drift. 0 freezes it. */
  speed?: number;
  /** Noise frequency. Lower = larger, sweepier landforms. */
  scale?: number;
  /** Number of contour bands. More = denser line packing. */
  levels?: number;
  /** Line thickness in CSS pixels. Stays constant regardless of field steepness. */
  lineWidth?: number;
  /** Line opacity. 0.16 matches the reference's barely-there look. */
  opacity?: number;
  /** Line colour. Any CSS color string. */
  color?: string;
  /** Slow translation across the field, in units/sec. Adds sideways drift. */
  drift?: [number, number];
  /** Domain warp strength. 0 = smooth blobs, ~0.2 = meandering, terrain-like. */
  warp?: number;
  /** Noise-units panned per scrolled pixel [x, y]. Scrolling travels across
   *  the field, so each section sits on a different part of the map. */
  scrollPan?: [number, number];
  /** How hard the pan follows the scroll, 0..1, as a fraction closed per frame
   *  at 60Hz (and rescaled to whatever the real frame rate is). `1` locks the
   *  map to the scrollbar, which is what makes a wheel notch jump it ~100px in
   *  one frame; lower values glide between the notches. Ignored when
   *  `scrollPan` is `[0, 0]`. Default `0.18`. */
  scrollEase?: number;
  /** Override the scroll value the pan reads. Lets the host freeze the map's
   *  travel across a range (e.g. a pinned scene) by clamping scrollY. */
  getPanScroll?: () => number;
  /** Scroll-driven recolouring. `at` is progress 0..1; between two stops the
   *  line colour/opacity is lerped, outside the band the nearest stop holds.
   *  Overrides `color`/`opacity` when present. Stops MUST be sorted by `at`
   *  ascending; an unsorted list silently picks the wrong segment. */
  colorStops?: ColorStop[];
  /** Progress source (0..1) that drives `colorStops`. Defaults to document
   *  scroll progress, the original component's behaviour. */
  getProgress?: () => number;
  /** Cap on devicePixelRatio. This is fragment-bound, so 1.5 is plenty. */
  maxDpr?: number;
  /** Follow the cursor: raise the field near the pointer so contour rings
   *  bloom around it. Listens on window pointermove only while enabled. */
  interactive?: boolean;
  /** Peak height of the mouse bump when `interactive`. */
  mouseStrength?: number;
  /** Falloff radius of the mouse bump, in field (stBase) units. */
  mouseRadius?: number;
}

/** Options with every non-callback field resolved to a concrete value. */
interface Resolved {
  seed: string;
  speed: number;
  scale: number;
  levels: number;
  lineWidth: number;
  opacity: number;
  color: string;
  drift: [number, number];
  warp: number;
  scrollPan: [number, number];
  scrollEase: number;
  maxDpr: number;
  interactive: boolean;
  mouseStrength: number;
  mouseRadius: number;
  getPanScroll?: () => number;
  colorStops?: ColorStop[];
  getProgress?: () => number;
}

/** Defaults IDENTICAL to the source component's props. */
export const DEFAULTS: Resolved = {
  seed: "topo",
  speed: 0.012,
  scale: 1.15,
  levels: 11,
  lineWidth: 1.2,
  opacity: 0.16,
  color: "#C3D82C",
  drift: [0.004, 0.002],
  warp: 0.18,
  scrollPan: [0, 0],
  scrollEase: 0.18,
  maxDpr: 1.5,
  interactive: false,
  mouseStrength: 0.35,
  mouseRadius: 0.35,
};

/** Keys whose value may legitimately be cleared back to `undefined`. */
const NULLABLE: ReadonlySet<string> = new Set([
  "colorStops",
  "getPanScroll",
  "getProgress",
]);

/** Apply a partial over a resolved option set, in place. `undefined` clears the
 *  nullable callback/array keys and is IGNORED everywhere else, so a patch that
 *  passes `{ speed: undefined }` keeps the current speed instead of pushing
 *  NaN into a uniform and blanking the field. */
function applyPatch(base: Resolved, patch: TopolinesOptions): void {
  (Object.keys(patch) as (keyof TopolinesOptions)[]).forEach((k) => {
    const v = patch[k];
    if (v !== undefined || NULLABLE.has(k)) {
      (base as unknown as Record<string, unknown>)[k] = v;
    }
  });
}

const clamp01 = (n: number): number => Math.min(1, Math.max(0, n));

export class TopoField {
  /** False when WebGL/derivatives are unavailable — the constructor then
   *  mounted nothing and every method is a no-op. */
  public ok = false;

  /** True while the GL context is lost. The canvas stays mounted and the field
   *  rebuilds itself and resumes when the browser restores the context. */
  public contextLost = false;

  private host: HTMLElement;
  private live: Resolved;

  // GL state — only valid when `ok` and not `contextLost`.
  private canvas!: HTMLCanvasElement;
  private gl!: WebGLRenderingContext;
  private program!: WebGLProgram;
  private buffer!: WebGLBuffer | null;
  private uRes!: WebGLUniformLocation | null;
  private uTime!: WebGLUniformLocation | null;
  private uSeed!: WebGLUniformLocation | null;
  private uScale!: WebGLUniformLocation | null;
  private uLevels!: WebGLUniformLocation | null;
  private uLineWidth!: WebGLUniformLocation | null;
  private uOpacity!: WebGLUniformLocation | null;
  private uColor!: WebGLUniformLocation | null;
  private uDrift!: WebGLUniformLocation | null;
  private uWarp!: WebGLUniformLocation | null;
  private uScrollOff!: WebGLUniformLocation | null;
  private uMouse!: WebGLUniformLocation | null;
  private uMouseBump!: WebGLUniformLocation | null;
  private uMouseRadius!: WebGLUniformLocation | null;

  private reduceMotion!: MediaQueryList;
  private io?: IntersectionObserver;
  private ro?: ResizeObserver;
  private dprQuery?: MediaQueryList;

  // Runtime state.
  private width = 0;
  private height = 0;
  private clock = 0; // accumulated animation time, independent of wall clock
  private last = 0;
  private raf = 0;
  private visible = true;
  private running = false;
  private destroyed = false;
  private seedX = 0;
  private seedY = 0;

  // Mouse state. `client*` is the raw viewport position from the last event,
  // `mouseN*` its normalized (scale-free, DPR-free) form, `mouse*` the smoothed
  // value in stBase space, and `bump` the eased strength sent to the shader.
  private pointerBound = false;
  private clientX = 0;
  private clientY = 0;
  private mouseNX = 0;
  private mouseNY = 0;
  private mouseX = 0;
  private mouseY = 0;
  /** The canvas rect, cached until something that can move it fires. Null
   *  means "read it next time it is actually needed". */
  private rect: DOMRect | null = null;
  private rectAge = 0;
  /** The eased scroll position the pan is drawn from, and whether it has been
   *  seeded from the real one yet. */
  private pan = 0;
  private panReady = false;
  private bump = 0;
  private pointerInside = false;

  constructor(host: HTMLElement, options: TopolinesOptions = {}) {
    this.host = host;
    this.live = { ...DEFAULTS };
    applyPatch(this.live, options);
    const [sx, sy] = seedOffset(this.live.seed);
    this.seedX = sx;
    this.seedY = sy;

    // A FRESH canvas per instance. React dev StrictMode mounts an effect
    // mount → cleanup → mount on the same DOM node; cleanup calls
    // loseContext(), which kills that canvas's context forever, and a reused
    // canvas would hand the second mount the same dead context back.
    const canvas = document.createElement("canvas");
    canvas.style.cssText = "display:block;width:100%;height:100%";
    host.appendChild(canvas);
    this.canvas = canvas;

    const gl = canvas.getContext("webgl", {
      alpha: true,
      antialias: false,
      depth: false,
      stencil: false,
      premultipliedAlpha: true,
      // preserveDrawingBuffer stays false: snapshot() draws and reads in the
      // same tick, so we get correct pixels without the perf cost.
      powerPreference: "low-power",
    });

    // No WebGL (or software-blocked): drop the canvas so whatever is behind the
    // host — e.g. a static fallback — shows through.
    const bail = (): void => {
      gl?.getExtension("WEBGL_lose_context")?.loseContext();
      if (canvas.parentNode === host) host.removeChild(canvas);
      this.ok = false;
    };
    if (!gl) {
      bail();
      return;
    }
    this.gl = gl;

    // setupGL covers the derivatives extension and the program. Either missing
    // means we can't render this correctly, so bail rather than draw wrong.
    if (!this.setupGL()) {
      bail();
      return;
    }

    this.reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    this.resize();

    // Don't burn GPU on a background that isn't on screen.
    this.io = new IntersectionObserver(([entry]) => {
      this.visible = entry.isIntersecting;
      if (this.visible) this.start();
      else this.stop();
    });
    this.io.observe(canvas);

    this.ro = new ResizeObserver(() => {
      this.rect = null;
      this.resize();
      if (!this.running) this.render(); // keep it correct while paused
    });
    this.ro.observe(canvas);

    // Browsers cap the number of live WebGL contexts and evict the oldest. A
    // page with a hero plus a gallery can cross that line, so recover instead
    // of going permanently black.
    canvas.addEventListener("webglcontextlost", this.onContextLost);
    canvas.addEventListener("webglcontextrestored", this.onContextRestored);

    document.addEventListener("visibilitychange", this.onVisibility);
    this.reduceMotion.addEventListener("change", this.onMotionChange);
    this.watchDpr();
    if (this.live.interactive) this.bindPointer();

    this.ok = true;
    this.render(); // paint immediately, before the first rAF
    this.start();
  }

  // -------------------------------------------------------------- public API

  /** Live-update options. Never rebuilds the program or context. */
  setOptions(patch: TopolinesOptions): void {
    if (patch.seed !== undefined && patch.seed !== this.live.seed) {
      const [sx, sy] = seedOffset(patch.seed);
      this.seedX = sx;
      this.seedY = sy;
    }

    const wasInteractive = this.live.interactive;
    applyPatch(this.live, patch);

    if (this.ok && this.live.interactive !== wasInteractive) {
      if (this.live.interactive) {
        this.bindPointer();
      } else {
        this.unbindPointer();
        this.pointerInside = false;
      }
    }

    // Reflect changes right away on paused / reduced-motion instances. resize()
    // runs first because maxDpr may have changed the backing-store size.
    if (this.ok && !this.running) {
      this.resize();
      this.render();
    }
  }

  play(): void {
    if (this.ok) this.start();
  }

  pause(): void {
    if (this.ok) this.stop();
  }

  /** Set the accumulated animation time directly. */
  setClock(t: number): void {
    this.clock = t;
    if (this.ok && !this.running) this.render();
  }

  /** Render one frame and read it back as a data URL. Returns null when not ok
   *  or while the context is lost. Draw-then-read in the same tick is required
   *  because the context is not preserveDrawingBuffer. */
  snapshot(): string | null {
    if (!this.ok || this.contextLost) return null;
    this.resize();
    this.render();
    return this.canvas.toDataURL("image/png");
  }

  /** Full teardown: stop the loop, disconnect observers, remove listeners,
   *  delete GL objects, force the context loss, drop the canvas. */
  destroy(): void {
    if (!this.ok) return;
    // Set before loseContext() so a queued webglcontextlost can't resurrect us.
    this.destroyed = true;
    this.stop();
    this.io?.disconnect();
    this.ro?.disconnect();
    this.dprQuery?.removeEventListener("change", this.onDprChange);
    this.canvas.removeEventListener("webglcontextlost", this.onContextLost);
    this.canvas.removeEventListener(
      "webglcontextrestored",
      this.onContextRestored
    );
    document.removeEventListener("visibilitychange", this.onVisibility);
    this.reduceMotion.removeEventListener("change", this.onMotionChange);
    this.unbindPointer();
    this.gl.deleteBuffer(this.buffer);
    this.gl.deleteProgram(this.program);
    this.gl.getExtension("WEBGL_lose_context")?.loseContext();
    if (this.canvas.parentNode === this.host) this.host.removeChild(this.canvas);
    this.ok = false;
  }

  // ---------------------------------------------------------------- internals

  /** (Re)create everything that lives inside the GL context: the derivatives
   *  extension, program, buffer, attribute and uniform locations, blend state.
   *  Runs at construction and again after `webglcontextrestored`, which
   *  invalidates every object the previous context handed out. */
  private setupGL(): boolean {
    const gl = this.gl;

    // fwidth() lives behind an extension in WebGL1. Without it we can't keep
    // line width uniform, so report failure rather than render something wrong.
    if (!gl.getExtension("OES_standard_derivatives")) return false;

    const program = buildProgram(gl);
    if (!program) return false;

    const buffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    // One oversized triangle covers the viewport with no wasted vertices.
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 3, -1, -1, 3]),
      gl.STATIC_DRAW
    );

    const aPos = gl.getAttribLocation(program, "aPos");
    gl.enableVertexAttribArray(aPos);
    gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

    const u = (n: string) => gl.getUniformLocation(program, n);
    this.program = program;
    this.buffer = buffer;
    this.uRes = u("uRes");
    this.uTime = u("uTime");
    this.uSeed = u("uSeed");
    this.uScale = u("uScale");
    this.uLevels = u("uLevels");
    this.uLineWidth = u("uLineWidth");
    this.uOpacity = u("uOpacity");
    this.uColor = u("uColor");
    this.uDrift = u("uDrift");
    this.uWarp = u("uWarp");
    this.uScrollOff = u("uScrollOff");
    this.uMouse = u("uMouse");
    this.uMouseBump = u("uMouseBump");
    this.uMouseRadius = u("uMouseRadius");

    gl.useProgram(program);
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA); // premultiplied
    return true;
  }

  /** Pointer listeners cost a layout read per frame per instance, so they only
   *  go on while `interactive` is actually set. */
  private bindPointer(): void {
    if (this.pointerBound) return;
    this.pointerBound = true;
    window.addEventListener("pointermove", this.onPointerMove);
    document.documentElement.addEventListener(
      "pointerleave",
      this.onPointerLeave
    );
    window.addEventListener("blur", this.onPointerLeave);
    /* capture, so a nested scroller counts too: anything that moves the
       element under the cursor has to drop the cached rect */
    window.addEventListener("scroll", this.onScroll, {
      passive: true,
      capture: true,
    });
  }

  private unbindPointer(): void {
    if (!this.pointerBound) return;
    this.pointerBound = false;
    window.removeEventListener("pointermove", this.onPointerMove);
    document.documentElement.removeEventListener(
      "pointerleave",
      this.onPointerLeave
    );
    window.removeEventListener("blur", this.onPointerLeave);
    window.removeEventListener("scroll", this.onScroll, { capture: true });
  }

  /** devicePixelRatio changes (window dragged to a different-density display)
   *  don't change the element's CSS size, so ResizeObserver never fires. Watch
   *  the resolution media query instead, or a paused instance keeps a stale
   *  backing store and renders blurry. */
  private watchDpr(): void {
    this.dprQuery?.removeEventListener("change", this.onDprChange);
    const dpr = window.devicePixelRatio || 1;
    this.dprQuery = window.matchMedia(`(resolution: ${dpr}dppx)`);
    this.dprQuery.addEventListener("change", this.onDprChange);
  }

  private start = (): void => {
    // prefers-reduced-motion: paint one static frame (done elsewhere), never loop.
    if (this.running || !this.visible || this.contextLost) return;
    if (this.reduceMotion.matches) return;
    this.running = true;
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.frame);
  };

  private stop = (): void => {
    this.running = false;
    cancelAnimationFrame(this.raf);
  };

  private frame = (now: number): void => {
    // Clamp dt so a backgrounded tab doesn't jump the pattern on return.
    const dt = Math.min((now - this.last) / 1000, 0.1);
    this.last = now;
    /* NO resize() here. It reads clientWidth, which flushes style and layout,
       and doing that inside rAF on every frame is a self-inflicted stall on any
       page with a live DOM. Every way the size can change already has an event
       behind it: the ResizeObserver for CSS size, the resolution media query
       for a DPR change. */
    this.clock += dt * this.live.speed;
    this.tickMouse(dt);
    this.tickPan(dt);
    this.render();
    this.raf = requestAnimationFrame(this.frame);
  };

  private tickMouse(dt: number): void {
    const p = this.live;
    const active = p.interactive && this.pointerInside;
    // Nothing to ease and nothing to follow: skip the layout read entirely.
    if (!active && this.bump === 0) return;

    if (active) {
      /* the rect is cached, not read per frame: it can only move when the
         element resizes, the page scrolls or the density changes, and all
         three invalidate it. That takes the last forced layout out of the
         frame - the loop below is now arithmetic and one draw.
         The half-second backstop is for everything else that can move an
         element and fire none of those: a CSS transition on an ancestor, a
         late image pushing the page around. Twice a second is not a cost; a
         permanently stale rect would be a bug. */
      this.rectAge += dt;
      if (this.rectAge > 0.5) {
        this.rectAge = 0;
        this.rect = null;
      }
      if (!this.rect) this.rect = this.canvas.getBoundingClientRect();
      const rect = this.rect;
      const w = rect.width;
      const h = rect.height;
      if (w > 0 && h > 0) {
        // Convert to gl_FragCoord's bottom-left origin, then to the normalized,
        // scale-free stN space (DPR cancels because it is a ratio).
        const fx = this.clientX - rect.left;
        const fy = h - (this.clientY - rect.top);
        const m = Math.min(w, h);
        this.mouseNX = (fx - 0.5 * w) / m;
        this.mouseNY = (fy - 0.5 * h) / m;
      }
    }

    // Ease the bump toward strength while the pointer is in the viewport and
    // interactive is on, else toward 0. Snap the tail to exactly 0 so the
    // early-out above can engage once the bump has visually finished.
    const target = active ? p.mouseStrength : 0;
    this.bump += (target - this.bump) * fri(0.08, dt);
    if (!active && Math.abs(this.bump) < 1e-4) this.bump = 0;

    // Lerp the smoothed position toward the live target (scale can change).
    const tx = this.mouseNX * p.scale;
    const ty = this.mouseNY * p.scale;
    const k = fri(0.06, dt);
    this.mouseX += (tx - this.mouseX) * k;
    this.mouseY += (ty - this.mouseY) * k;
  }

  /** The scroll pan, eased. The raw value steps: a wheel notch is ~100px at
   *  once, and a field panned straight off `scrollY` jumps that far in one
   *  frame while everything else on the page is still gliding. Following it
   *  instead keeps the map moving continuously between notches, and costs the
   *  pan a few frames of lag that nothing is synchronised to anyway.
   *  `scrollEase: 1` is the old behaviour, locked to the scrollbar. */
  private tickPan(dt: number): void {
    const p = this.live;
    if (p.scrollPan[0] === 0 && p.scrollPan[1] === 0) return;
    const target = p.getPanScroll ? p.getPanScroll() : window.scrollY || 0;
    /* the first frame has nowhere to ease from: a field that mounts halfway
       down a restored scroll position must start there, not travel there */
    if (!this.panReady) {
      this.panReady = true;
      this.pan = target;
      return;
    }
    this.pan += (target - this.pan) * fri(p.scrollEase, dt);
  }

  private progress(): number {
    if (this.live.getProgress) return clamp01(this.live.getProgress());
    if (typeof window === "undefined") return 0;
    const doc = document.documentElement;
    return clamp01(
      (window.scrollY || 0) / Math.max(1, doc.scrollHeight - window.innerHeight)
    );
  }

  private resize(): void {
    if (this.contextLost) return;
    const dpr = Math.min(window.devicePixelRatio || 1, this.live.maxDpr);
    const w = Math.max(1, Math.round(this.canvas.clientWidth * dpr));
    const h = Math.max(1, Math.round(this.canvas.clientHeight * dpr));
    if (w === this.width && h === this.height) return;
    this.width = w;
    this.height = h;
    this.canvas.width = w;
    this.canvas.height = h;
    this.gl.viewport(0, 0, w, h);
  }

  private render = (): void => {
    if (this.contextLost) return;
    const p = this.live;
    const gl = this.gl;
    /* a frame painted while the loop is stopped - a resize, a restored context,
       the single static frame of reduced motion - still has to sit at the real
       scroll position rather than at the top of the page */
    if (!this.panReady) this.tickPan(0);

    let r: number;
    let g: number;
    let b: number;
    let alpha: number;

    const s = p.colorStops;
    if (s && s.length) {
      // Scroll-driven recolouring between stops (see colorStops docs). Stops
      // are assumed sorted by `at` ascending.
      const prog = this.progress();
      const first = s[0];
      const last = s[s.length - 1];
      if (prog <= first.at) {
        [r, g, b] = parseColor(first.color);
        alpha = first.opacity;
      } else if (prog >= last.at) {
        [r, g, b] = parseColor(last.color);
        alpha = last.opacity;
      } else {
        let lo = first;
        let hi = last;
        for (let i = 0; i < s.length - 1; i++) {
          if (prog >= s[i].at && prog <= s[i + 1].at) {
            lo = s[i];
            hi = s[i + 1];
            break;
          }
        }
        const t = (prog - lo.at) / (hi.at - lo.at || 1e-6);
        const ca = parseColor(lo.color);
        const cb = parseColor(hi.color);
        r = ca[0] + (cb[0] - ca[0]) * t;
        g = ca[1] + (cb[1] - ca[1]) * t;
        b = ca[2] + (cb[2] - ca[2]) * t;
        alpha = lo.opacity + (hi.opacity - lo.opacity) * t;
      }
    } else {
      // Only parse the base colour when no stop overrides it.
      [r, g, b] = parseColor(p.color);
      alpha = p.opacity;
    }

    gl.uniform2f(this.uRes, this.width, this.height);
    gl.uniform1f(this.uTime, this.clock);
    gl.uniform2f(this.uSeed, this.seedX, this.seedY);
    gl.uniform1f(this.uScale, p.scale);
    gl.uniform1f(this.uLevels, p.levels);
    gl.uniform1f(this.uLineWidth, p.lineWidth);
    gl.uniform1f(this.uOpacity, alpha);
    gl.uniform3f(this.uColor, r, g, b);
    gl.uniform2f(this.uDrift, p.drift[0], p.drift[1]);
    gl.uniform1f(this.uWarp, p.warp);
    // Scroll pans the field, so the map slides to a different region as the
    // page moves. Y is negated — scrolling down should feel like travelling
    // "up" the chart. The value is the eased one from tickPan(); a paused
    // instance repainting once still reads the last position it settled on.
    const sy2 = this.pan;
    gl.uniform2f(this.uScrollOff, sy2 * p.scrollPan[0], -sy2 * p.scrollPan[1]);
    gl.uniform2f(this.uMouse, this.mouseX, this.mouseY);
    gl.uniform1f(this.uMouseBump, this.bump);
    // Clamp radius so the shader's exp(-d/r^2) never divides by zero.
    gl.uniform1f(this.uMouseRadius, Math.max(p.mouseRadius, 1e-3));

    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
  };

  private onContextLost = (e: Event): void => {
    // Without preventDefault the browser never fires webglcontextrestored.
    e.preventDefault();
    this.contextLost = true;
    this.stop();
  };

  private onContextRestored = (): void => {
    if (this.destroyed) return;
    this.contextLost = false;
    if (!this.setupGL()) {
      // Restored into a context we can't use. Stay lost rather than draw
      // garbage; `ok` stays true so the host's layout doesn't shift.
      this.contextLost = true;
      return;
    }
    // Force resize(): the drawing buffer and viewport did not survive.
    this.width = 0;
    this.height = 0;
    this.resize();
    this.render();
    this.start();
  };

  private onVisibility = (): void => {
    if (document.hidden) this.stop();
    else this.start();
  };

  private onMotionChange = (): void => {
    this.stop();
    this.resize();
    this.render(); // always paint one static frame
    this.start();
  };

  private onDprChange = (): void => {
    this.watchDpr(); // re-arm the query against the new ratio
    this.rect = null;
    this.resize();
    if (!this.running) this.render();
  };

  /** Scrolling moves the element without resizing it, so it is the third and
   *  last thing that can invalidate the cached rect. Passive, and it does one
   *  assignment - the read itself is deferred to the frame that needs it. */
  private onScroll = (): void => {
    this.rect = null;
  };

  private onPointerMove = (e: PointerEvent): void => {
    // Store raw viewport coords only. The element rect is read once per frame
    // in tickMouse() instead, so one mouse move can't force layout N times on
    // a page with several fields.
    this.pointerInside = true;
    this.clientX = e.clientX;
    this.clientY = e.clientY;
  };

  private onPointerLeave = (): void => {
    this.pointerInside = false;
  };
}
